<script setup lang="ts">import {ref,onMounted} from 'vue';import {reviews} from '../stores/reviews';import {reports} from '../stores/reports';import {isAdmin} from '../stores/auth';import {request,downloadCsv} from '../api/client';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import StatusPill from '../components/common/StatusPill.vue';import BudgetStrip from '../components/BudgetStrip.vue';const expanded=ref('');const {error,busy,act}=useTask();onMounted(()=>Promise.all([reviews.load(),reports.load()]));function approve(id:string){act(async()=>{await request('/reviews/'+id+'/approve','POST');await reviews.load()})}function publish(id:string){act(async()=>{await reports.create({review_id:id,title:'因子敏感度底稿 '+new Date().toLocaleDateString()})})}function download(id:string){act(()=>downloadCsv(id))}</script><template><PageHeading index="05 / 试验归档" title="把范围、假设和采样量，一并签入底稿。" note="主管批准后才生成不可变报告。CSV含物理范围、归一EE、样本sigma分母、S1/ST原值、评估数与输入哈希。"/><Notice :message="error"/><div class="two-col"><section><h2>待审与已审因子复核</h2><article v-for="r in reviews.items.value" :key="r.id" class="review-row"><StatusPill :status="r.state"/><p>{{r.action}}</p><small>{{r.reviewer||'等待主管批准'}}</small><div v-if="isAdmin()" class="actions"><button v-if="r.state==='submitted'" @click="approve(r.id)" :disabled="busy">批准因子复核</button><button v-if="r.state==='approved'" class="secondary" @click="publish(r.id)" :disabled="busy">生成敏感度快照</button></div></article></section><section><h2>批准试验底稿</h2><article v-for="r in reports.items.value" :key="r.id" class="report-row"><p class="eyebrow">APPROVED FACTOR RECORD</p><h3>{{r.title}}</h3><p>{{r.snapshot.result.study_name}}</p><p>{{r.snapshot.result.metrics.length}}因子 · seed {{r.snapshot.result.config.seed}} · {{r.snapshot.reviewer}}</p><div class="actions"><button @click="download(r.id)">下载敏感度 CSV ↓</button><button class="secondary" @click="expanded=expanded===r.id?'':r.id">查看采样预算</button></div><BudgetStrip v-if="expanded===r.id" :result="r.snapshot.result"/></article></section></div></template>
